// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.recording/** * NOUS — Recording Policy (Module 11 v3 — Step 11.5, P1). * * Per-contact recording preference (Strategy §"CallRecordingEngine" — * "Per-contact policy (always / never / ask)"). * * The default policy is [ASK] — NOUS never records a call without explicit * user consent. The user can override per-contact in Settings → Privacy → * Call Recording. * * - [ALWAYS] — record every call with this contact automatically. * - [NEVER] — never record; if user asks "record this call" the engine *   refuses and surfaces the policy override. * - [ASK] — prompt the user with a 5s "Record?" confirmation dialog. */enum class RecordingPolicy(val displayLabel: String) {    ALWAYS("Always Record"),    NEVER("Never Record"),    ASK("Ask Each Time");    companion object {        /** Parse from storage string (case-insensitive; falls back to [ASK]). */        fun fromString(value: String?): RecordingPolicy =            entries.firstOrNull { it.name.equals(value, ignoreCase = true) } ?: ASK    }}